        System.out.println("调用后 arr[0] = " + arr[0]);
        System.out.println("调用后 arr[2] = " + arr[2]);
    }

    public static void change(int[] a) {
        a[0] = a[0] + 10;
        a = new int[]{100, 200, 300};
